const http=require('http'),fs=require('fs'),path=require('path');const root=path.resolve('artifacts/forum-v2/preview');http.createServer((q,r)=>{let p=q.url.split('?')[0];let f=p.startsWith('/brand/')?path.join(process.cwd(),'public',p):path.join(root,p==='/'||p==='/forum'?'index.html':p);fs.readFile(f,(e,b)=>{r.statusCode=e?404:200;r.setHeader('Content-Type',f.endsWith('.css')?'text/css':f.endsWith('.js')?'text/javascript':f.endsWith('.webp')?'image/webp':'text/html');r.end(e?'missing':b);});}).listen(4319,'127.0.0.1');
